  const bubble = document.createElement('div');
  bubble.className = `bubble ${cls || ''}`;
  // User messages are plain text, bot messages support markdown
  if (role === 'bot') {
    // Try to parse as data-aware JSON first
    let isDataAware = false;
    try {
        const trimmed = text.trim();
        if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
            const data = JSON.parse(trimmed);
            if (data.type === 'data_preview') {
                renderDataPreview(data, bubble);
                isDataAware = true;
            } else if (data.type === 'export_request') {
                handleExportRequest(data, bubble);
                isDataAware = true;
            }
        }
    } catch (e) { /* fallback to markdown */ }

    if (!isDataAware) {
        bubble.innerHTML = markdownToHTML(text);
    }

    // Add copy button for bot messages

    const copyBtn = document.createElement('button');
    copyBtn.className = 'copy-btn';
    copyBtn.textContent = 'Copy';
    copyBtn.onclick = () => copyMessage(text, copyBtn);
    bubble.appendChild(copyBtn);
  } else {
    bubble.textContent = text;
  }

  msg.appendChild(avatar);
  msg.appendChild(bubble);
  messagesEl.appendChild(msg);
  messagesEl.scrollTop = messagesEl.scrollHeight;
  return bubble;
}

function copyMessage(text, btn) {
  navigator.clipboard.writeText(text).then(() => {
    const originalText = btn.textContent;
    btn.textContent = 'Copied!';
    btn.classList.add('copied');
    setTimeout(() => {
      btn.textContent = originalText;
      btn.classList.remove('copied');
    }, 2000);
  }).catch(err => {
    console.error('Failed to copy:', err);
  });
}

function downloadConversation() {
  if (conversationHistory.length === 0) {
    alert('No conversation to download yet!');
    return;
  }

  // Build markdown format
  let markdown = '# Safecast Radiation Assistant Conversation\n\n';
  markdown += `Date: ${new Date().toLocaleString()}\n\n`;
  markdown += '---\n\n';

  conversationHistory.forEach(msg => {
    const role = msg.role === 'user' ? 'You' : 'Assistant';
    markdown += `## ${role}\n\n`;
    markdown += msg.content + '\n\n';
    markdown += '---\n\n';
  });

