    function addMessageUI(role, text) {
      const row = document.createElement('div');
      row.className = `ai-msg-row ${role}`;

      const avatar = document.createElement('div');
      avatar.className = 'ai-avatar';
      if (role === 'user') {
        avatar.innerHTML = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path><circle cx="12" cy="7" r="4"></circle></svg>';
      } else {
        avatar.innerHTML = 'i';
      }

      const bubble = document.createElement('div');
      bubble.className = 'ai-bubble';

      if (role === 'bot') {
        bubble.innerHTML = markdownToHTML(text);
      } else {
        bubble.textContent = text;
      }

      const ts = document.createElement('div');
      ts.className = 'ai-timestamp';
      ts.textContent = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

      const wrapper = document.createElement('div');
      wrapper.appendChild(bubble);
      wrapper.appendChild(ts);

      row.appendChild(avatar);
      row.appendChild(wrapper);
      messagesEl.appendChild(row);
      messagesEl.scrollTop = messagesEl.scrollHeight;
      return bubble;
    }

    function executeMapAction(actionData) {
      if (!actionData || typeof map === 'undefined') return;
      try {
        if (actionData.action === 'panTo' && actionData.lat !== undefined && actionData.lon !== undefined) {
          map.panTo([actionData.lat, actionData.lon]);
        } else if (actionData.action === 'zoomTo' && actionData.level !== undefined) {
          map.setZoom(actionData.level);
        } else if (actionData.action === 'highlightLocation' && actionData.lat !== undefined && actionData.lon !== undefined) {
          const marker = L.circleMarker([actionData.lat, actionData.lon], {
            radius: 20,
            color: '#FF0000',
            fillColor: '#FF0000',
            fillOpacity: 0.3
          }).addTo(map);
          setTimeout(() => {
            if (map.hasLayer(marker)) map.removeLayer(marker);
          }, 5000);
        }
      } catch (e) {
        console.error("Action execution failed:", e);
      }
    }

    function sendFeedback(chatID, score, upBtn, downBtn) {
      fetch('/api/feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ chat_id: chatID, score }),
      }).catch(() => {});
      upBtn.disabled = true;
      downBtn.disabled = true;
      const row = upBtn.parentElement;
      row.classList.add('voted');
      if (score > 0) upBtn.classList.add('active');
      else downBtn.classList.add('active');
    }

    function addFeedbackRow(wrapper, chatID, isCached) {
      const row = document.createElement('div');
      row.className = 'ai-feedback-row';

      if (isCached) {
        const badge = document.createElement('span');
        badge.className = 'ai-cached-badge';
        badge.textContent = '⚡ cached';
        row.appendChild(badge);
      }

      const upBtn = document.createElement('button');
      upBtn.className = 'ai-feedback-btn';
      upBtn.innerHTML = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3H14z"/><path d="M7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"/></svg>';
      upBtn.title = 'Helpful';

      const downBtn = document.createElement('button');
      downBtn.className = 'ai-feedback-btn';
      downBtn.innerHTML = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 15v4a3 3 0 0 0 3 3l4-9V2H5.72a2 2 0 0 0-2 1.7l-1.38 9a2 2 0 0 0 2 2.3H10z"/><path d="M17 2h2.67A2.31 2.31 0 0 1 22 4v7a2.31 2.31 0 0 1-2.33 2H17"/></svg>';
      downBtn.title = 'Not helpful';

      upBtn.onclick   = () => sendFeedback(chatID, 1,  upBtn, downBtn);
      downBtn.onclick = () => sendFeedback(chatID, -1, upBtn, downBtn);

      row.appendChild(upBtn);
      row.appendChild(downBtn);
      wrapper.appendChild(row);
    }

    function submitMessage() {
      const text = msgInput.value.trim();
      if (!text || busy) return;

      busy = true;
      sendBtn.disabled = true;

      addMessageUI('user', text);
      const botBubble = addMessageUI('bot', translate('ai_thinking'));
      botBubble.classList.add('ai-thinking');

      msgInput.value = '';
      msgInput.style.height = '44px';

      let accumulated = '';
      let chatID = 0;
      let isCached = false;
      let finished = false;
      function finish(success) {
        if (finished) return;
        finished = true;
        botBubble.classList.remove('ai-thinking');
        busy = false;
        sendBtn.disabled = false;
        msgInput.focus();
        if (success && accumulated) {
          chatHistory.push(
            { role: 'user', content: text },
            { role: 'assistant', content: accumulated }
          );
          if (chatHistory.length > 10) {
            chatHistory = chatHistory.slice(-10);
          }
          if (chatID) {
            const wrapper = botBubble.parentElement;
            addFeedbackRow(wrapper, chatID, isCached);
          }
        }
      }

      var chatPayload = {
        message: text,
        history: chatHistory,
        map_context: getMapContext(),
        source: 'widget',
        lang: currentLang,
        client_timestamp: new Date().toISOString()
      };
      if (typeof currentTrackID !== 'undefined' && currentTrackID) {
        chatPayload.track_id = currentTrackID;
      }
      fetch('/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(chatPayload),
      }).then(response => {
        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffer = '';

        function pump() {
          return reader.read().then(({ done, value }) => {
            if (done) { finish(true); return; }

            buffer += decoder.decode(value, { stream: true });
            const lines = buffer.split('\n');
            buffer = lines.pop();

            for (const line of lines) {
              if (!line.trim()) continue;
              try {
                const ev = JSON.parse(line);
                if (ev.type === 'text') {
                  if (botBubble.classList.contains('ai-thinking')) {
                    botBubble.classList.remove('ai-thinking');
                    accumulated = '';
                  }
                  accumulated += ev.text;
                  botBubble.innerHTML = markdownToHTML(accumulated);
                  messagesEl.scrollTop = messagesEl.scrollHeight;
                } else if (ev.type === 'action' || ev.action) {
                  executeMapAction(ev);
                } else if (ev.type === 'done') {
                  if (ev.chat_id) { chatID = ev.chat_id; isCached = !!ev.cached; }
                  finish(true);
                } else if (ev.type === 'error') {
                  botBubble.textContent = translate('ai_error') + ev.error;
                  botBubble.classList.remove('ai-thinking');
                  finish(false);
                }
              } catch (e) { }
            }
            return pump();
          });
        }
        return pump();
      }).catch(err => {
        botBubble.textContent = translate('ai_connection_error') + err.message;
        botBubble.classList.remove('ai-thinking');
        finish(false);
      });
    }

    // Expose renderers for the Track Insights button script.
    window.markdownToHTML = markdownToHTML;
